package com.optarena.app

class TokenBucket(private val capacity: Double, private val refillRate: Double) {
    private var tokens: Double = capacity
    private var last: Double? = null

    fun allow(now: Double): Boolean {
        last?.let { lastTime ->
            val elapsed = now - lastTime
            tokens = minOf(capacity, tokens + elapsed * refillRate)
        }
        last = now
        if (tokens >= 1) {
            tokens -= 1
            return true
        }
        return false
    }
}

