package com.optarena.app

import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class TokenBucketTest {
    @Test
    fun startsFullAndDrains() {
        val b = TokenBucket(3.0, 1.0)
        assertTrue(b.allow(0.0))
        assertTrue(b.allow(0.0))
        assertTrue(b.allow(0.0))
        assertFalse(b.allow(0.0))
    }

    @Test
    fun refillsOverTime() {
        val b = TokenBucket(3.0, 1.0)
        repeat(3) { b.allow(0.0) }
        assertFalse(b.allow(0.5))
        assertTrue(b.allow(1.0))
        assertFalse(b.allow(1.0))
    }

    @Test
    fun refillCapsAtCapacity() {
        val b = TokenBucket(2.0, 1.0)
        b.allow(0.0)
        b.allow(0.0)
        assertTrue(b.allow(1000.0))
        assertTrue(b.allow(1000.0))
        assertFalse(b.allow(1000.0))
    }
}
